package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.tiles.ScreenHousingTextures;
/** Exact released Light menu filter, including raw redirected and company Light entries. */
public final class LightPickerLegacyChecks {
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();JsonArray rows=new JsonArray();int onCount=0,offCount=0;for(int choice=0;choice<ScreenHousingTextures.IDS.length;choice++){boolean include=HousingTextureList.generalTexture(choice)||"Lights".equals(ScreenHousingTextures.category(choice))||ScreenHousingTextures.lightOnly(choice);boolean off=ScreenHousingTextures.visible(choice)&&include,on=off&&!ScreenHousingTextures.isLightOff(choice);if(on)onCount++;if(off)offCount++;JsonObject row=new JsonObject();row.addProperty("choice",choice);row.addProperty("on",on);row.addProperty("off",off);rows.add(row);}String json=rows.toString();java.nio.file.Path output=java.nio.file.Paths.get(args[0]);java.nio.file.Files.createDirectories(output.toAbsolutePath().getParent());java.nio.file.Files.write(output,json.getBytes("UTF-8"));StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(json.getBytes("UTF-8")))hash.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(rows.size()!=893||onCount!=263||offCount!=289||!hash.toString().equals("18c15ed5b1150d747fddf92502d5ca71c5be2d448a4d85703127e34738b62b8e"))throw new AssertionError("Source Light picker changed "+hash);System.out.println("Actual Light picker PASS choices="+rows.size()+" on="+onCount+" off="+offCount+" golden="+hash);}
}
